def build_tree(paths: list) -> dict:
    tree = {}
    for path in paths:
        parts = path.split('/')
        current = tree
        for i, part in enumerate(parts):
            if i == len(parts) - 1:
                current[part] = None
            else:
                if part not in current or current[part] is None:
                    current[part] = {}
                current = current[part]
    return dict(sorted(tree.items(), key=lambda x: (x[1] is None, x[0])))

def _sort_tree(tree):
    if tree is None:
        return None
    sorted_tree = {}
    items = sorted(tree.items(), key=lambda x: (x[1] is None, x[0]))
    for k, v in items:
        sorted_tree[k] = _sort_tree(v)
    return sorted_tree

def print_tree(tree: dict, prefix: str = '') -> str:
    tree = _sort_tree(tree)
    lines = []
    items = list(tree.items())
    for i, (name, subtree) in enumerate(items):
        is_last = i == len(items) - 1
        connector = '└── ' if is_last else '├── '
        lines.append(prefix + connector + name)
        if subtree is not None:
            extension = '    ' if is_last else '│   '
            lines.append(print_tree(subtree, prefix + extension))
    return '\n'.join(lines)

