function buildTree(paths) {
  const tree = {};
  for (const path of paths) {
    const parts = path.split('/');
    let current = tree;
    for (let i = 0; i < parts.length; i++) {
      if (i === parts.length - 1) {
        current[parts[i]] = null;
      } else {
        if (!(parts[i] in current) || current[parts[i]] === null) {
          current[parts[i]] = {};
        }
        current = current[parts[i]];
      }
    }
  }
  return sortTree(tree);
}

function sortTree(tree) {
  if (tree === null) return null;
  const sorted = {};
  const entries = Object.entries(tree).sort((a, b) => {
    const aIsFile = a[1] === null;
    const bIsFile = b[1] === null;
    if (aIsFile !== bIsFile) return aIsFile ? 1 : -1;
    return a[0].localeCompare(b[0]);
  });
  for (const [k, v] of entries) sorted[k] = sortTree(v);
  return sorted;
}

function printTree(tree, prefix = '') {
  const entries = Object.entries(sortTree(tree));
  const lines = [];
  entries.forEach(([name, subtree], i) => {
    const isLast = i === entries.length - 1;
    lines.push(prefix + (isLast ? '└── ' : '├── ') + name);
    if (subtree !== null) {
      lines.push(printTree(subtree, prefix + (isLast ? '    ' : '│   ')));
    }
  });
  return lines.join('\n');
}
